            for (j = 0; j < vblCounter; j++) {
                pOriginalPoints[j] = new POINT2_1.POINT2(pLinePoints[j]);
            }
            let numSegs = 0;
            let d = 0;
            lineutility_1.lineutility.InitializePOINT2Array(xPoints);
            for (j = 0; j < vblCounter - 1; j++) {
                d = lineutility_1.lineutility.CalcDistanceDouble(pOriginalPoints[j], pOriginalPoints[j + 1]);
                numSegs = Math.trunc(d / length);
                for (k = 0; k < numSegs; k++) {
                    pt0 = lineutility_1.lineutility.ExtendAlongLineDouble2(pOriginalPoints[j], pOriginalPoints[j + 1], length * k);
                    pt0.style = 0;
                    pt1 = lineutility_1.lineutility.ExtendAlongLineDouble2(pOriginalPoints[j], pOriginalPoints[j + 1], length * k + length / 2);
                    pt1.style = 5;
                    pt2 = lineutility_1.lineutility.ExtendAlongLineDouble2(pOriginalPoints[j], pOriginalPoints[j + 1], length * k + length / 2);
                    pt2.style = 20; //for filled circle
                    pLinePoints[counter++] = new POINT2_1.POINT2(pt0);
                    pLinePoints[counter++] = new POINT2_1.POINT2(pt1);
                    xPoints[xCounter++] = new POINT2_1.POINT2(pt2);
                }
                if (numSegs === 0) {
                    pLinePoints[counter] = new POINT2_1.POINT2(pOriginalPoints[j]);
                    pLinePoints[counter++].style = 0;
                    pLinePoints[counter] = new POINT2_1.POINT2(pOriginalPoints[j + 1]);
                    pLinePoints[counter++].style = 5;
                }
                else {
                    pLinePoints[counter] = new POINT2_1.POINT2(pLinePoints[counter - 1]);
                    pLinePoints[counter++].style = 0;
                    pLinePoints[counter] = new POINT2_1.POINT2(pOriginalPoints[j + 1]);
                    pLinePoints[counter++].style = 5;
                }
            }
            //load the circle points
            for (k = 0; k < xCounter; k++) {
                pLinePoints[counter++] = new POINT2_1.POINT2(xPoints[k]);
            }
            //add one more circle
            pLinePoints[counter++] = new POINT2_1.POINT2(pLinePoints[counter]);
