                    pt0 = lineutility_1.lineutility.ExtendAlongLineDouble(midpt, pLinePoints[middleSegment], dMBR / 20, 0);
                    airPts.push(pt0);
                    pt1 = new POINT2_1.POINT2(pLinePoints[middleSegment]);
                    pt1.style = 5;
                    airPts.push(pt1);
                    pt0 = lineutility_1.lineutility.ExtendAlongLineDouble(midpt, pLinePoints[middleSegment - 1], dMBR / 20, 0);
                    airPts.push(pt0);
                    pt1 = new POINT2_1.POINT2(pLinePoints[middleSegment - 1]);
                    pt1.style = 5;
                    airPts.push(pt1);
                    //re-dimension pLinePoints so that it can hold the
