                    pLinePoints[1] = new POINT2_1.POINT2(pt1);
                    pts2 = new Array(3);
                    pts2[0] = new POINT2_1.POINT2(pt0);
                    pts2[1] = new POINT2_1.POINT2(pt1);
                    pts2[2] = new POINT2_1.POINT2(pt2);
                    lineutility_1.lineutility.GetPixelsMin(pts2, 3, offsetX, offsetY);
